claims=[]
def claim(start,end,label,assessment,ids,kind='STATISTIC_OR_FINANCIAL_ASSUMPTION'):
 pat=r'\s+'.join(re.escape(x) for x in start.split());m=re.search(pat,S);assert m,start;a=m.start()
 if end:
  m2=re.search(r'\s+'.join(re.escape(x) for x in end.split()),S[m.end():]);assert m2,end;b=m.end()+m2.end()
 else:b=m.end()
 claims.append(dict(claim_id=f'C{len(claims)+1:02}',start_char=a,end_char=b,original_quote=S[a:b],claim_type=kind,classification=label,assessment=assessment,source_ids=ids))
